CREATE OR REPLACE FUNCTION public.correct_class_session(p_session_id uuid, p_session_date date, p_session_number integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current public.class_sessions%rowtype;
begin
  if auth.uid() is null then
    raise exception '請先登入。';
  end if;
  if p_session_date is null then
    raise exception '請填寫有效上課日期。';
  end if;
  if p_session_number is not null and (p_session_number < 1 or p_session_number > 999) then
    raise exception '上課次數必須是 1 到 999 的整數。';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 1 and 500 then
    raise exception '請說明修正原因，最多 500 字。';
  end if;
  select * into v_current
  from public.class_sessions
  where id = p_session_id and owner_id = auth.uid()
  for update;
  if not found then
    raise exception '找不到這堂課。';
  end if;
  if p_session_number is not null and exists (
    select 1 from public.class_sessions
    where owner_id = auth.uid() and course_id = v_current.course_id
      and session_number = p_session_number and id <> p_session_id
  ) then
    raise exception '這個班級已有相同的上課次數。';
  end if;
  if v_current.session_date is not distinct from p_session_date
     and v_current.session_number is not distinct from p_session_number then
    return;
  end if;
  insert into public.class_session_corrections (
    owner_id, course_id, class_session_id,
    previous_session_date, next_session_date,
    previous_session_number, next_session_number, reason
  ) values (
    auth.uid(), v_current.course_id, v_current.id,
    v_current.session_date, p_session_date,
    v_current.session_number, p_session_number, btrim(p_reason)
  );
  update public.class_sessions
  set session_date = p_session_date, session_number = p_session_number
  where id = v_current.id and owner_id = auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.correct_classroom_record(p_record_type text, p_record_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner_id uuid := auth.uid();
  v_course_id uuid;
  v_student_id uuid;
  v_previous_status text;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_owner_id is null then
    raise exception '請先登入。';
  end if;
  if p_record_type is null or p_record_type not in ('randomizer_attempt', 'learning_event') then
    raise exception '回答紀錄類型不正確。';
  end if;
  if p_record_id is null then
    raise exception '找不到要修正的回答紀錄。';
  end if;
  if char_length(v_reason) not between 1 and 500 then
    raise exception '請說明修正原因，最多 500 字。';
  end if;

  if p_record_type = 'randomizer_attempt' then
    select course_id, student_id, record_status
      into v_course_id, v_student_id, v_previous_status
    from public.randomizer_attempts
    where id = p_record_id and owner_id = v_owner_id
    for update;

    if not found then
      raise exception '找不到這筆回答紀錄。';
    end if;
    if v_previous_status = 'corrected' then
      raise exception '這筆回答紀錄已更正。';
    end if;
    if v_previous_status = 'voided' then
      raise exception '這筆回答紀錄已撤銷。';
    end if;

    update public.randomizer_attempts
    set record_status = 'corrected',
        counted_for_summary = false,
        correction_note = v_reason,
        corrected_at = now()
    where id = p_record_id and owner_id = v_owner_id;
  else
    select course_id, student_id, record_status
      into v_course_id, v_student_id, v_previous_status
    from public.learning_events
    where id = p_record_id and owner_id = v_owner_id
    for update;

    if not found then
      raise exception '找不到這筆回答紀錄。';
    end if;
    if v_previous_status = 'corrected' then
      raise exception '這筆回答紀錄已更正。';
    end if;
    if v_previous_status = 'voided' then
      raise exception '這筆回答紀錄已撤銷。';
    end if;

    update public.learning_events
    set record_status = 'corrected',
        counted_for_summary = false,
        correction_note = v_reason,
        corrected_at = now()
    where id = p_record_id and owner_id = v_owner_id;
  end if;

  insert into public.classroom_record_corrections (
    owner_id, record_type, record_id, course_id, student_id,
    previous_record_status, next_record_status, reason
  ) values (
    v_owner_id, p_record_type, p_record_id, v_course_id, v_student_id,
    v_previous_status, 'corrected', v_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_class_session(p_course_id uuid, p_session_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_session public.class_sessions%rowtype;
begin
  if auth.uid() is null then raise exception '请先登录教师账号。'; end if;
  if p_session_date is null then raise exception '请填写有效上课日期。'; end if;
  perform 1 from public.courses where id=p_course_id and owner_id=auth.uid() for update;
  if not found then raise exception '找不到本班或没有访问权限。'; end if;
  select * into v_session from public.class_sessions
    where course_id=p_course_id and owner_id=auth.uid() and status='in_progress';
  if found then
    if v_session.session_date <> p_session_date then
      raise exception '本班 % 的课次尚未收尾，不能写入 % 的记录。请先核对并完成旧课次；本机记录已保留。', v_session.session_date, p_session_date;
    end if;
    return v_session.id;
  end if;
  if exists (select 1 from public.class_sessions
    where course_id=p_course_id and owner_id=auth.uid() and session_date=p_session_date) then
    raise exception '本班 % 已有结束的课堂。补记请在学生管理系统选择原课次，不另建重复课堂。', p_session_date;
  end if;
  insert into public.class_sessions(owner_id,course_id,session_date,status)
    values(auth.uid(),p_course_id,p_session_date,'in_progress') returning id into v_session.id;
  return v_session.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_randomizer_class(p_client_session_id text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_class_id uuid; v_course_id uuid; v_completed_at timestamptz;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select class_session_id, course_id into v_class_id, v_course_id
    from public.randomizer_sessions
    where owner_id = auth.uid() and client_session_id = p_client_session_id;
  if v_class_id is null then raise exception 'Class session not found'; end if;
  select coalesce(completed_at, now()) into v_completed_at from public.class_sessions
    where id = v_class_id and course_id = v_course_id and owner_id = auth.uid() for update;
  if not found then raise exception 'Class session not accessible'; end if;
  update public.randomizer_sessions set status = 'completed', completed_at = coalesce(completed_at, v_completed_at)
    where class_session_id = v_class_id and course_id = v_course_id and owner_id = auth.uid();
  update public.class_sessions set status = 'completed', completed_at = v_completed_at
    where id = v_class_id and course_id = v_course_id and owner_id = auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_class_session_start()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.courses where id=new.course_id and owner_id=new.owner_id for update;
  if exists(select 1 from public.class_sessions
    where owner_id=new.owner_id and course_id=new.course_id and session_date=new.session_date) then
    raise exception '本班该日期已有课堂，请连接原课次。' using errcode='23505';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_class_session_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.owner_id is distinct from old.owner_id or new.course_id is distinct from old.course_id then
    raise exception 'Classroom identity cannot be reassigned';
  end if;
  if old.status='completed' and new.status<>'completed' then
    raise exception 'Completed classrooms cannot be reopened by a stale write';
  end if;
  if new.session_date is distinct from old.session_date then
    perform 1 from public.courses where id=new.course_id and owner_id=new.owner_id for update;
    if exists(select 1 from public.class_sessions where owner_id=new.owner_id
      and course_id=new.course_id and session_date=new.session_date and id<>new.id) then
      raise exception 'This class already has a session on that date' using errcode='23505';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_enrollment_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='UPDATE' and new.owner_id=old.owner_id and new.course_id=old.course_id
    and new.student_id=old.student_id then return new; end if;
  if exists (
    select 1 from public.class_sessions s
    where s.owner_id=old.owner_id and s.course_id=old.course_id and (
      exists(select 1 from public.attendance_records a where a.owner_id=old.owner_id and a.session_id=s.id and a.student_id=old.student_id)
      or exists(select 1 from public.observation_records a where a.owner_id=old.owner_id and a.session_id=s.id and a.student_id=old.student_id)
      or exists(select 1 from public.attendance_exceptions a where a.owner_id=old.owner_id and a.session_id=s.id and a.student_id=old.student_id)
    )
  ) then
    raise exception 'Enrollment has classroom evidence; retain it and change its status instead'
      using errcode='23503';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_randomizer_attempt_replay()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.randomizer_session_id<>old.randomizer_session_id or new.course_id<>old.course_id
    or new.owner_id<>old.owner_id or new.client_attempt_id<>old.client_attempt_id then
    raise exception '发言记录不能在重试时改挂另一堂课。';
  end if;
  if old.record_status='corrected' and new.record_status<>'corrected' then return old; end if;
  if new.assessment_status in ('pending','not_applicable') and old.source_updated_at is not null and (new.source_updated_at is null
    or new.source_updated_at<old.source_updated_at) then return old; end if;
  if old.assessment_status in ('observed','scored') and new.assessment_status in ('pending','not_applicable') then
    new.assessment_status := old.assessment_status;
    new.performance_level := old.performance_level;
    new.observation_version := old.observation_version;
    new.fact_marks := old.fact_marks;
    new.fact_version := old.fact_version;
    new.task_completion := old.task_completion;
    new.comprehensibility := old.comprehensibility;
    new.language_control_vocabulary := old.language_control_vocabulary;
    new.content_interaction := old.content_interaction;
    new.total_score := old.total_score;
    new.score := old.score;
    new.counted_for_grade := old.counted_for_grade;
    new.counted_for_summary := old.counted_for_summary;
    new.outcome := old.outcome;
    new.response_status := old.response_status;
    new.completed_at := old.completed_at;
    new.no_response_reason := old.no_response_reason;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_randomizer_class_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_class public.class_sessions%rowtype;
begin
  if tg_op='UPDATE' and (new.class_session_id<>old.class_session_id or new.course_id<>old.course_id
    or new.owner_id<>old.owner_id or new.client_session_id<>old.client_session_id) then
    raise exception '抽问记录已关联固定课次，不能在重试时改挂另一堂课。';
  end if;
  select * into v_class from public.class_sessions
    where id=new.class_session_id and owner_id=new.owner_id and course_id=new.course_id;
  if not found then raise exception '找不到对应的课堂。'; end if;
  new.session_date := v_class.session_date;
  if v_class.status='completed' then
    new.status := 'completed';
    new.completed_at := coalesce(new.completed_at,v_class.completed_at,now());
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.interact_classroom(p_action text, p_room uuid DEFAULT NULL::uuid, p_token text DEFAULT ''::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 r public.interact_rooms;
 token_hash text;
 teacher boolean;
 q jsonb;
 item jsonb;
 v jsonb;
 qs jsonb;
 result_answers jsonb;
begin
 if p_token is null or length(p_token) < 32 or length(p_token) > 128 then raise exception '请刷新页面后重试。'; end if;
 token_hash := encode(sha256(convert_to(p_token,'UTF8')),'hex');
 if p_action = 'create' then
  if length(btrim(coalesce(p_data->>'title',''))) not between 1 and 120 then raise exception '课堂名称须为 1 至 120 个字。'; end if;
  insert into public.interact_rooms(teacher_hash,title) values(token_hash,btrim(p_data->>'title')) returning * into r;
 else
  -- Serialize writes against stopping/launching; submissions never replace other answers.
  if p_action = 'read' then select * into r from public.interact_rooms where id=p_room;
  else select * into r from public.interact_rooms where id=p_room for update; end if;
  if r.id is null then raise exception '找不到这个课堂，请重新扫描二维码。'; end if;
 end if;
 teacher := r.teacher_hash = token_hash;
 if p_action in ('update','end') then
  if teacher is not true then raise exception '只有老师可以操作课堂。'; end if;
  if p_action = 'end' then
   update public.interact_rooms set ended=true, revision=revision+1 where id=r.id returning * into r;
  else
   if r.ended then raise exception '课堂已结束。'; end if;
   if (p_data->>'revision')::int is distinct from r.revision then raise exception '课堂已更新，请重试。'; end if;
   qs := p_data->'questions';
   if jsonb_typeof(qs) is distinct from 'array' then raise exception '题目格式错误。'; end if;
   if jsonb_array_length(qs)>200 or octet_length(qs::text)>500000 then raise exception '本堂题目已达上限，请创建新课堂。'; end if;
   for item in select value from jsonb_array_elements(qs) loop
    if coalesce(item->>'type', '') not in ('open_response','poll','multiple_choice','true_false','short_answer')
      or coalesce(item->>'status', '') not in ('active','stopped')
      or length(btrim(coalesce(item->>'promptText',''))) not between 1 and 4000
      or jsonb_typeof(item->'options') is distinct from 'array'
      or jsonb_typeof(item->'correctAnswers') is distinct from 'array'
      or jsonb_typeof(item->'allowMultiple') is distinct from 'boolean'
      or item->>'id' is null then raise exception '题目格式错误。'; end if;
    perform (item->>'id')::uuid;
   end loop;
   if (select count(*) from jsonb_array_elements(qs) x where x->>'status'='active')>1 then raise exception '一次只能开放一道题。'; end if;
   update public.interact_rooms set questions=qs,revision=revision+1 where id=r.id returning * into r;
  end if;
 elsif p_action = 'answer' then
  if r.ended then raise exception '课堂已结束。'; end if;
  select value into q from jsonb_array_elements(r.questions) where value->>'id'=p_data->>'questionId' and value->>'status'='active';
  if q is null then raise exception '老师已停止作答，请等待下一题。'; end if;
  if length(btrim(coalesce(p_data->>'name',''))) not between 1 and 80 then raise exception '请输入姓名（最多 80 个字）。'; end if;
  v := p_data->'value';
  if q->>'type' in ('open_response','short_answer') then
   if jsonb_typeof(v) is distinct from 'string' or length(btrim(v#>>'{}')) not between 1 and 2000 then raise exception '请输入答案（最多 2000 个字）。'; end if;
  elsif (q->>'allowMultiple')::boolean then
   if jsonb_typeof(v) is distinct from 'array' then raise exception '请选择答案。'; end if;
   if jsonb_array_length(v)<1 or jsonb_array_length(v)>jsonb_array_length(q->'options') then raise exception '请选择有效选项。'; end if;
   if exists(select 1 from jsonb_array_elements(v) a where jsonb_typeof(a) <> 'string' or not (q->'options' @> jsonb_build_array(a))) then raise exception '请选择有效选项。'; end if;
   if (select count(distinct a) from jsonb_array_elements(v) a)<>jsonb_array_length(v) then raise exception '选项不能重复。'; end if;
  else
   if jsonb_typeof(v) is distinct from 'string' or not(q->'options' @> jsonb_build_array(v)) then raise exception '请选择有效选项。'; end if;
  end if;
  -- Reusing a request ID makes a network retry safe for repeatable responses.
  if not exists(select 1 from public.interact_responses where id=(p_data->>'id')::uuid and room_id=r.id and participant_hash=token_hash) then
   if exists(select 1 from public.interact_responses where room_id=r.id and participant_hash=token_hash and created_at>now()-interval '1 second') then raise exception '请稍候再提交。'; end if;
   begin
    insert into public.interact_responses(id,room_id,question_id,participant_hash,participant_name,value,once_only)
     values((p_data->>'id')::uuid,r.id,(q->>'id')::uuid,token_hash,btrim(p_data->>'name'),v,q->>'type'<>'open_response');
   exception when unique_violation then raise exception '这道题已提交答案。'; end;
  end if;
 elsif p_action not in ('read','create') then raise exception '不支持的操作。';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'questionId',question_id,'participantId',participant_hash,'participantName',participant_name,'value',value,'submittedAt',created_at) order by created_at),'[]') into result_answers
 from public.interact_responses where room_id=r.id and (teacher or participant_hash=token_hash);
 select coalesce(jsonb_agg(case when teacher then x else x || jsonb_build_object('correctAnswers','[]'::jsonb) end),'[]') into qs from jsonb_array_elements(r.questions) x;
 return jsonb_build_object('title',r.title,'code',r.id,'createdAt',r.created_at,'questions',qs,'answers',result_answers,'revision',r.revision,'ended',r.ended);
end $function$

CREATE OR REPLACE FUNCTION public.keep_corrected_classroom_records_out_of_summary()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and old.record_status in ('corrected', 'voided') then
    new := old;
  end if;
  if new.record_status in ('corrected', 'voided') then
    new.counted_for_summary := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.keep_randomizer_session_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = 'completed' then
    new.status := 'completed';
    new.completed_at := old.completed_at;
    new.class_session_id := old.class_session_id;
    new.course_id := old.course_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_attendance_exception_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.class_sessions s
    join public.enrollments e on e.course_id = s.course_id and e.owner_id = s.owner_id
    where s.id = new.session_id and s.owner_id = new.owner_id and e.student_id = new.student_id
  ) then
    raise exception 'Student does not belong to this classroom' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_session_student_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.class_sessions s
    join public.enrollments e on e.owner_id=s.owner_id and e.course_id=s.course_id
    where s.id=new.session_id and s.owner_id=new.owner_id and e.student_id=new.student_id
  ) then
    raise exception 'Student does not belong to this classroom' using errcode='23514';
  end if;
  return new;
end;
$function$
